require "application_system_test_case"

class ZzDndExperimentTest < ApplicationSystemTestCase
  setup do
    sign_in_as(users(:david))
  end

  test "native drag probe" do
    visit board_url(boards(:writebook))
    assert_selector "#article_card_#{cards(:text).id}", visible: :all
    page.execute_script(<<~JS)
      window.__log = [];
      const card = document.getElementById("article_card_#{cards(:text).id}");
      card.setAttribute("draggable", "true");
      document.addEventListener("dragstart", e => window.__log.push("dragstart:" + e.target.id), true);
      document.addEventListener("dragenter", e => window.__log.push("dragenter:" + e.target.id), true);
      document.addEventListener("drop", e => window.__log.push("drop:" + e.target.closest("section")?.id), true);
      document.addEventListener("dragover", e => { e.preventDefault(); }, true);
      document.addEventListener("dragend", e => window.__log.push("dragend"), true);
      document.addEventListener("mousedown", e => window.__log.push("mousedown:" + e.target.tagName), true);
    JS
    src = find("#article_card_#{cards(:text).id}")
    dst = find("#column_#{columns(:writebook_on_hold).id}")
    src.drag_to(dst)
    puts "LOG: #{page.evaluate_script("window.__log").inspect}"
  end
end
EOF
